    /*
     * Assign a Asset
     * 
     * @param	parentId	UUID
     * @param	assignment 	Asset 
     * @return	MaintenancePlan
     */
    public MaintenancePlan assignAsset( UUID parentId, Asset assignment ) {
	    LOGGER.info("assigning Asset as " + assignment.toString() );

	    MaintenancePlan parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Asset.class, assignment.getAssetId());

	    // ------------------------------------------
		// assign the Asset to the parent entity
		// ------------------------------------------ 
	    parentEntity.setAsset( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Asset
	 * 
	 * @param	parentId		UUID
	 * @return	MaintenancePlan
	 */
	public MaintenancePlan unAssignAsset( UUID parentId ) {
		MaintenancePlan parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Asset on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Asset on the parent entithy
		// ------------------------------------------     
	    parentEntity.setAsset(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the MaintenanceOrders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	MaintenancePlan
     */
    public MaintenancePlan addToMaintenanceOrders( UUID parentId, MaintenanceOrder addTo ) {
	    LOGGER.info("handling AssignMaintenanceOrdersToMaintenancePlanEvent - " );
	    
	    MaintenancePlan parentEntity = repository.findById(parentId).get();
	    MaintenanceOrder child = registry.project( MaintenanceOrder.class, addTo.getMaintenanceOrderId());
	    
	    parentEntity.getMaintenanceOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the MaintenanceOrders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	MaintenancePlan
     */
	public MaintenancePlan removeFromMaintenanceOrders( UUID parentId, MaintenanceOrder removeFrom ) {
	    LOGGER.info("handling RemoveMaintenanceOrdersFromMaintenancePlanEvent " );
	
	    MaintenancePlan parentEntity = repository.findById(parentId).get();
	    MaintenanceOrder child = registry.project( MaintenanceOrder.class, removeFrom.getMaintenanceOrderId());
	    
	    parentEntity.getMaintenanceOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



